/**
 * @param {number[]} nums1
 * @param {number[]} nums2
 * @return {number}
 */
var maxDistance = function(nums1, nums2) {
    let max = 0;

    for (let i = 0; i < nums1.length; i++) {
        for (let j = i; j < nums2.length; j++) {
            if (nums1[i] > nums2[j]) {
                break;
            }

            max = Math.max(max, j - i);
        }
    }

    return max;
};

/**
 * @param {number[]} nums1
 * @param {number[]} nums2
 * @return {number}
 */
var maxDistance = function(nums1, nums2) {
    let pos1 = 0;
    let pos2 = 0;
    let max = 0;

    while (pos1 < nums1.length && pos2 < nums2.length) {
        if (nums1[pos1] > nums2[pos2]) {
            pos1++;
            if (pos2 < pos1) {
                pos2 = pos1;
            }
            continue;
        }

        max = Math.max(max, pos2 - pos1);
        pos2++;
    }

    return max;
};
